var i=`0306-banitsa`;var n=`world-0306`;var a=`BG`;var o=`eastern-europe`;var r=4;var s=57;var l={en:`Banitsa`,ua:`Баніца`};var g={en:`A traditional Bulgaria dish made with feta, plain yogurt, chicken egg, phyllo pastry. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Болгарія. Основні інгредієнти: фета, натуральний йогурт, куряче яйце, тісто філо. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:7,i:[[`feta`,300,`g`],[`plain-yogurt`,240,`g`],[`chicken-egg`,3,`pcs`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:14,i:[[`phyllo-pastry`,400,`g`],[`unsalted-butter`,115,`g`]]},{en:`Bake in a preheated 180°C oven for about 36 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 36 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:36,i:[]}];var u={slug:i,id:n,country:`BG`,region:o,servings:4,minutes:57,title:l,text:g,steps:h};export{a as country,u as default,n as id,s as minutes,o as region,r as servings,i as slug,h as steps,g as text,l as title};